import { useCallback, useEffect, useState } from 'react';
import { useCustomerType } from '@salesforce/commerce-sdk-react';
import { RECENTLY_VIEWED_HISTORY_MAX_STORED } from 'app/constants';

/**
 * Storage key backing the Recently Viewed interim history (see `useRecentlyViewedHistory`
 * below). Shared by both storage backends (`sessionStorage` for guests, `localStorage` for
 * registered shoppers) — safe, since the two are separate namespaces and can never collide.
 * Exported as a single named constant so every reader/writer agrees on it, per conventions.md's
 * no-magic-strings rule.
 *
 * Renamed from the pre-revision `RECENTLY_VIEWED_SESSION_KEY` (same literal value): this key now
 * holds a JSON-encoded array of product IDs, not a boolean flag string, so the old name no longer
 * described its contents.
 */
export const RECENTLY_VIEWED_HISTORY_STORAGE_KEY = 'zimm-recently-viewed';

const EMPTY_IDS: readonly string[] = [];

export type RecentlyViewedHistory = {
  hasRecentlyViewed: boolean;
  recentlyViewedIds: readonly string[];
  markProductViewed: (productId: string) => void;
};

/**
 * Reads and parses the stored ID list off a given `Storage`. Tolerant of every failure mode a
 * real browser can produce: the key missing entirely, `JSON.parse` failing on corrupt data, a
 * parsed value that isn't an array, or the storage access itself throwing (Safari private-
 * browsing mode throws on both `sessionStorage` and `localStorage` access, not just on write).
 * Every failure degrades to "no history" rather than propagating.
 */
const readStoredIds = (storage: Storage): string[] => {
  try {
    const raw = storage.getItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === 'string') : [];
  } catch {
    return [];
  }
};

/**
 * Writes the given ID list to a `Storage`, JSON-encoded. Wrapped in try/catch: Safari private-
 * browsing mode throws on `setItem`, and a real device can also legitimately hit a storage quota.
 * Either way this degrades to "no write happens" rather than throwing further and breaking the
 * PDP view-tracking effect this is called from.
 *
 * @returns `true` if the write succeeded, `false` if it was silently swallowed.
 */
const writeStoredIds = (storage: Storage, ids: readonly string[]): boolean => {
  try {
    storage.setItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY, JSON.stringify(ids));
    return true;
  } catch {
    return false;
  }
};

/**
 * Moves `productId` to the front of `ids`, removing any existing occurrence first (never a
 * duplicate — a re-view of an already-seen product correctly becomes "most recent" again), then
 * trims to `RECENTLY_VIEWED_HISTORY_MAX_STORED`, oldest-first (i.e. from the tail).
 */
const dedupeAndPrepend = (ids: readonly string[], productId: string): string[] => {
  const withoutExisting = ids.filter((id) => id !== productId);
  return [productId, ...withoutExisting].slice(0, RECENTLY_VIEWED_HISTORY_MAX_STORED);
};

