import { describe, expect, test, vi } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useProducts } from '@salesforce/commerce-sdk-react';
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { useRecentlyViewedProductFetch } from './recentlyViewedProductFetch';

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useProducts: vi.fn(),
}));

const mockUseProducts = vi.mocked(useProducts);

// Minimal but distinct per id, so a mis-mapped/mis-ordered result is loudly wrong rather than
// coincidentally matching (same doctrine as recentlyViewedCard.test.ts's own fixtures).
const product = (id: string): ShopperProductsTypes.Product => ({ id, name: `Product ${id}` });

function mockProducts(data: ShopperProductsTypes.Product[] | undefined, isLoading = false) {
  mockUseProducts.mockReturnValue({
    data: data ? { limit: data.length, total: data.length, data } : undefined,
    isLoading,
  } as unknown as ReturnType<typeof useProducts>);
}

describe('useRecentlyViewedProductFetch', () => {
  test('calls useProducts with the confirmed parameter combination and a comma-joined ids string', () => {
    mockProducts([product('A'), product('B')]);

    renderHook(() => useRecentlyViewedProductFetch(['A', 'B']));

    expect(mockUseProducts).toHaveBeenCalledWith(
      {
        parameters: {
          ids: 'A,B',
          allImages: true,
          perPricebook: true,
          expand: ['prices', 'promotions', 'images', 'variations'],
        },
      },
      { enabled: true },
    );
  });

  test('re-orders the API response to match the requested id order, regardless of response order', () => {
    // API returns B before A -- the opposite of request order.
    mockProducts([product('B'), product('A')]);

    const { result } = renderHook(() => useRecentlyViewedProductFetch(['A', 'B']));

    expect(result.current.products.map((p) => p.id)).toEqual(['A', 'B']);
  });

  test('silently drops an id the API did not return, without leaving a hole', () => {
    // Only B comes back -- A was requested but is offline/deleted.
    mockProducts([product('B')]);

    const { result } = renderHook(() => useRecentlyViewedProductFetch(['A', 'B']));

    expect(result.current.products.map((p) => p.id)).toEqual(['B']);
  });

  test('caps the request at the first 24 ids and never asks for more, even when given more', () => {
    const manyIds = Array.from({ length: 30 }, (_, i) => `ID-${i}`);
    mockProducts([]);

    renderHook(() => useRecentlyViewedProductFetch(manyIds));

    const expectedIds = manyIds.slice(0, 24).join(',');
    expect(mockUseProducts).toHaveBeenCalledWith(
      expect.objectContaining({ parameters: expect.objectContaining({ ids: expectedIds }) }),
      expect.anything(),
    );
  });

  test('products fetched beyond the 24-id cap are never returned, even if somehow present in the response', () => {
    const manyIds = Array.from({ length: 30 }, (_, i) => `ID-${i}`);
    // A response that (hypothetically) included data for an uncapped id must still not surface it
    // -- the cap is enforced on the read side too, not just the outgoing request.
    mockProducts(manyIds.map(product));

    const { result } = renderHook(() => useRecentlyViewedProductFetch(manyIds));

    expect(result.current.products).toHaveLength(24);
    expect(result.current.products.map((p) => p.id)).not.toContain('ID-24');
  });

  test('empty ids -> disables the query, returns no products, and reports isLoading false', () => {
    mockProducts(undefined, true);

    const { result } = renderHook(() => useRecentlyViewedProductFetch([]));

    expect(mockUseProducts).toHaveBeenCalledWith(expect.anything(), { enabled: false });
    expect(result.current.products).toEqual([]);
    // The underlying query mock claims isLoading: true even though disabled -- this hook must
    // not surface that, since no request was ever actually made.
    expect(result.current.isLoading).toBe(false);
  });

  test('isLoading reflects the underlying query only when there are ids to fetch', () => {
    mockProducts(undefined, true);

    const { result } = renderHook(() => useRecentlyViewedProductFetch(['A']));

    expect(result.current.isLoading).toBe(true);
  });

  test('no data yet (still loading) -> products is an empty array, not a throw', () => {
    mockProducts(undefined, true);

    const { result } = renderHook(() => useRecentlyViewedProductFetch(['A', 'B']));

    expect(result.current.products).toEqual([]);
  });
});

