 * Einstein-specific `rec`/flat-`image` wrapper fields `fetchRecProductDetails`
 * (`@salesforce/retail-react-app/app/hooks/use-einstein.js:465-505`) used to bolt on. This
 * mapper's own output contract and scope (image-only, no gallery, no was/now pricing — A2's
 * `recentlyViewed` variation decision, unchanged) are unaffected; only the shape of what it reads
 * on the way in changed, and with it, `selectPrimaryImage`'s fallback below: there is no longer a
 * separate flat Einstein image to fall back to, so "the selected `imageGroups` image has no
 * usable `src`" and "there is no usable image at all" are now the same case.
 *
 * Modelled on `overrides/app/pages/product-detail/productInfo.ts` — no React/react-intl import,
 * `formatPrice` injected as a parameter so this module stays independently testable — and on the
 * general shape of `liveProductCardDemoMapper.ts` (`feature/zimmproductcard-live-demo`, not this
 * branch — read for its approach, not imported). Unlike that demo mapper, this is a production
 * path: real `commerce-sdk-isomorphic` SDK types are used directly (AGENTS.md > Type
 * Definitions) — with the Einstein-specific input shape gone, there is no longer any hand-rolled
 * field on the input type at all.
 *
 * Deliberately narrow scope, stated here rather than left as a silent gap: this mapper only ever
 * returns `currentPrice` (an active selling price), not was/now sale-price detection
 * (`originalPrice`) — but that is a scope choice, not a data limitation. **Correction
 * (2026-09-08, pre-dates and is unaffected by the input-source revision above):** an earlier
 * version of this comment claimed the merged Einstein shape "has no equivalent of"
 * `getPriceData`-style pricebook logic — verified inaccurate, and equally true of the plain
 * `getProducts` shape this mapper now reads: `recentlyViewedProductFetch.ts` already requests
 * `perPricebook: true`, so `product.tieredPrices` is present, and base SFCC's `getPriceData`
 * (`app/utils/product-utils.js`) already derives `listPrice`/`isOnSale` from exactly that field —
 * nothing is missing, it's simply not called here. The real reason `originalPrice` isn't mapped is
 * that the `recentlyViewed` variation renders no price at all today (see
 * `zimmProductCard/index.tsx`'s `recentlyViewed` `VARIATION_CONFIG` row — `showContent: false`), so
 * there is nothing for it to feed. Mapping `currentPrice` anyway costs nothing and means a future
 * consumer of this same mapper (e.g. a variation that does render price) isn't blocked on this
 * file being revisited — extending it to also call `getPriceData` at that point would be a small,
 * well-precedented addition, not new pricebook work.
 */
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type { ZimmProductCardBaseProps, ZimmProductCardImage } from '../components/ui-kits/organisms/zimmProductCard';

/**
 * The real Commerce API `Product` (`commerce-sdk-isomorphic`'s own `ShopperProductsTypes.Product`
 * — not hand-rolled). A plain alias, not an augmentation: unlike the pre-revision Einstein-sourced
 * shape this replaces, `recentlyViewedProductFetch.ts`'s plain `getProducts` result needs nothing
 * bolted on — `Product.id` is used directly, and there is no separate flat-image field. Kept as a
 * named alias (rather than importing `ShopperProductsTypes.Product` directly at each call site)
 * so this module's own input type has a name that documents its role here.
 */
export type RecentlyViewedProduct = ShopperProductsTypes.Product;

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl,
 *  mirroring `productInfo.ts`'s own `FormatPrice` shape. */
export type FormatPrice = (amount: number, currency: string) => string;

/**
 * The subset of `ZimmProductCardBaseProps` this mapper populates. Deliberately excludes
 * `headingLevel` and `variation` — both are render-context decisions belonging to the container
 * step that maps recs through this mapper and renders the rail (SFCC-83's A6 step), which supplies
 * `headingLevel` uniformly for every card and adds `variation: 'recentlyViewed'` itself when
 * spreading this output into `<ZimmProductCard>` — the rail organism itself (A5) takes already-full
 * `ZimmProductCardProps` objects, so variation must already be set before it sees them. A pure data
 * mapper choosing a heading level would conflate a data concern with a layout one. Also excludes `hoverImage`/`images` — this
 * mapper only ever returns one image (`primaryImage`); see `selectPrimaryImage`'s own docblock
 * for why.
 */
export type RecentlyViewedCard = Pick<
  ZimmProductCardBaseProps,
  'id' | 'href' | 'name' | 'primaryImage' | 'currentPrice'
>;

/** The correctly-sized product image view, per AGENTS.md's image-sizing guidance: never serve an
 *  arbitrary-sized image at thumbnail size. Named rather than inlined per conventions.md's
 *  no-magic-strings rule — this is a real, semantic SFCC image `viewType` key. */
const MEDIUM_VIEW_TYPE = 'medium';

/**
 * Resolves the one image this mapper ever returns. `hoverImage`/`images` are never populated —
 * SFCC-83 AC 3 asks for "the product's index image" (singular), and the `recentlyViewed`
 * variation renders neither a hover-swap nor a gallery (see `zimmProductCard/index.tsx`'s
 * `recentlyViewed` row: `showHoverImageSwap: false`, and its render branch never forwards
 * `images` at all).
 *
 * Prefers `filterImageGroups` at `viewType: 'medium'` (a real, correctly-sized product image) —
 * `variationValues` is deliberately empty: a Recently Viewed rec is already one specific product,
 * not a search hit needing a variant pick the way `liveProductCardDemoMapper.ts`'s own
 * `resolveDemoVariant` handles, so that logic does not apply here. Falls back to Einstein's own
 * flat `image` field only when that filtering produces nothing usable — see
 * `RecentlyViewedProduct.image`'s own comment for what that field is.
 *
 * @returns `null` when neither source has a usable `src`. `ZimmProductCardMediaImage.alt` is
 *   required and non-empty, so there is no safe placeholder card to build without a real image —
 *   a card with an invented placeholder `src` would need an asset this codebase has no confirmed
 *   token or precedent for, so "no usable image" is treated the same as "no usable name" in
 *   `selectRecentlyViewedCard` below: a hard gate that yields no card at all. Returning `null`
 *   here is the only option that structurally cannot violate the non-empty-`alt` contract, since
 *   there is no returned object for `alt` to be empty on.
 */
const selectPrimaryImage = (product: RecentlyViewedProduct, productName: string): ZimmProductCardImage | null => {
  const filteredGroups = filterImageGroups(product.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: {},
  }) as ShopperProductsTypes.ImageGroup[];
  const [groupImage] = filteredGroups[0]?.images ?? [];

  const src = groupImage ? groupImage.disBaseLink || groupImage.link : product.image?.disBaseLink;
  if (!src) return null;

  // ZimmProductCardMediaImage.alt is required and non-empty (unlike base ProductTile's
  // decorative alt: '' convention) — mirrors liveProductCardDemoMapper.ts's own fallback exactly.
  const alt = (groupImage ? groupImage.alt : product.image?.alt)?.trim() || productName;
  return { src, alt };
};

/**
 * @param product - The merged Einstein rec + Commerce API product `fetchRecProductDetails`
 *   produces, or `undefined`/`null` while that data is not yet available.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the `recentlyViewed` `ZimmProductCard` variation, or `null` when the rec has
 *   no usable name or no usable image — never a broken card, never a throw.
 */
export const selectRecentlyViewedCard = (
  product: RecentlyViewedProduct | undefined | null,
  formatPrice: FormatPrice,
): RecentlyViewedCard | null => {
  if (!product?.name) return null;

  const primaryImage = selectPrimaryImage(product, product.name);
  if (!primaryImage) return null;

  return {
    // Reads productId, not the SDK Product's own `id` — see RecentlyViewedProduct.productId's
    // own comment for why (guaranteed equal in practice, but productId is the field the real
    // runtime hook explicitly produces this way).
    id: product.productId,
    href: productUrlBuilder({ id: product.productId }),
    name: product.name,
    primaryImage,
    // No hardcoded fallback currency — if either is absent, skip formatting rather than guess,
    // matching productInfo.ts's own "no hardcoded fallback currency" comment.
    currentPrice:
      typeof product.price === 'number' && product.currency ? formatPrice(product.price, product.currency) : undefined,
  };
};

input.content:
/**
 * Ties the plain Commerce API product shape (`recentlyViewedProductFetch.ts`'s own `getProducts`
 * result — see `recentlyViewedCard.ts`'s 2026-09-08 input-source revision) to the rendered
 * `ZimmProductCard` props, the same doctrine `productInfo.test.ts` documents as "G1": every
 * assertion below uses a value unique to its own field (see `FULL` below — the 'large' image
 * group's `alt` is deliberately a value that must never be picked) so a mapping that reads the
 * wrong key fails rather than coincidentally matching.
 *
 * Fixtures updated 2026-09-08 for the plain-product input shape: `productId` is gone (the mapper
 * now reads the SDK's own `id` directly — there is no second id-like field to confuse it with),
 * and there is no flat Einstein `image` fallback field any more (`imageGroups` is the only image
 * source) — the pre-revision "productId vs id" and "flat Einstein image fallback" tests are
 * removed below because their premise no longer exists in the mapper, not because coverage was
 * dropped without a reason.
 */
import { describe, expect, test, vi } from 'vitest';
import { selectRecentlyViewedCard, type FormatPrice, type RecentlyViewedProduct } from './recentlyViewedCard';

const formatPrice: FormatPrice = (amount, currency) => `${currency} ${amount.toFixed(2)}`;

const FULL: RecentlyViewedProduct = {
  id: 'REC-PRODUCT-ID-0001',
  name: 'Natura Mini Dress',
  price: 895,
  currency: 'AUD',
  imageGroups: [
    {
      viewType: 'medium',
      images: [
        {
          link: 'https://example.test/medium/natura-mini-dress-link.jpg',
          disBaseLink: 'https://cdn.example.test/medium/natura-mini-dress.jpg',
          alt: 'Natura Mini Dress, Ivory',
        },
      ],
    },
    {
      // Wrong viewType — must never be picked. If it is, this test's alt assertion fails.
      viewType: 'large',
      images: [
        { link: 'https://example.test/large/natura-mini-dress.jpg', alt: 'WRONG VIEWTYPE — MUST NOT BE PICKED' },
      ],
    },
  ],
};

describe('selectRecentlyViewedCard — happy path', () => {
  test('maps every field to its correct prop, picking the medium imageGroups image', () => {
    expect(selectRecentlyViewedCard(FULL, formatPrice)).toEqual({
      id: 'REC-PRODUCT-ID-0001',
      href: '/product/REC-PRODUCT-ID-0001',
      name: 'Natura Mini Dress',
      primaryImage: {
        src: 'https://cdn.example.test/medium/natura-mini-dress.jpg',
        alt: 'Natura Mini Dress, Ivory',
      },
      currentPrice: 'AUD 895.00',
    });
  });

  test('id and href are built from the product id', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice);
    expect(card?.id).toBe('REC-PRODUCT-ID-0001');
  });

  test('href is a bare /product/{id} path — no site-prefix of its own', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice);
    expect(card?.href).toBe('/product/REC-PRODUCT-ID-0001');
    expect(card?.href).not.toMatch(/^https?:\/\//);
  });

  test('omits headingLevel, variation, hoverImage and images entirely — not just empty', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice) as object | null;
    expect(card).not.toBeNull();
    expect(card).not.toHaveProperty('headingLevel');
    expect(card).not.toHaveProperty('variation');
    expect(card).not.toHaveProperty('hoverImage');
    expect(card).not.toHaveProperty('images');
  });
});

describe('selectRecentlyViewedCard — no usable name, no card', () => {
  test('returns null when name is missing', () => {
    expect(selectRecentlyViewedCard({ ...FULL, name: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when name is an empty string', () => {
    expect(selectRecentlyViewedCard({ ...FULL, name: '' }, formatPrice)).toBeNull();
  });

  test('returns null for a nullish product (still loading)', () => {
    expect(selectRecentlyViewedCard(undefined, formatPrice)).toBeNull();
    expect(selectRecentlyViewedCard(null, formatPrice)).toBeNull();
  });
});

describe('selectRecentlyViewedCard — no usable image, no card', () => {
  // Decision (documented, not silently made): "no usable image at all" is treated the same as
  // "no usable name" — a hard null gate — rather than a placeholder-image card. A placeholder
  // would need an asset/src this codebase has no confirmed token for, and null is the only
  // choice that structurally cannot violate ZimmProductCardMediaImage.alt's required-non-empty
  // contract (there is no returned object for alt to be empty on). See selectPrimaryImage's own
  // docblock in recentlyViewedCard.ts for the same note at the point of the decision.
  test('returns null when imageGroups is absent entirely (no flat-image fallback exists any more)', () => {
    expect(selectRecentlyViewedCard({ ...FULL, imageGroups: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when imageGroups is an empty array', () => {
    expect(selectRecentlyViewedCard({ ...FULL, imageGroups: [] }, formatPrice)).toBeNull();
  });

  test('returns null when imageGroups filtering matches nothing (no medium viewType)', () => {
    const noMediumGroup: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [{ viewType: 'large', images: [{ link: 'https://example.test/large-only.jpg' }] }],
    };
    expect(selectRecentlyViewedCard(noMediumGroup, formatPrice)).toBeNull();
  });

  test('returns null when the medium group has no images at all', () => {
    const emptyMediumGroup: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [{ viewType: 'medium', images: [] }],
    };
    expect(selectRecentlyViewedCard(emptyMediumGroup, formatPrice)).toBeNull();
  });
});

describe('selectRecentlyViewedCard — disBaseLink/alt fallbacks within the selected imageGroups image', () => {
  test('falls back to link when the selected medium image has no disBaseLink', () => {
    const linkOnlyMedium: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [
        {
          viewType: 'medium',
          images: [{ link: 'https://example.test/medium/link-only.jpg', alt: 'Natura Mini Dress, link-only' }],
        },
      ],
    };
    const card = selectRecentlyViewedCard(linkOnlyMedium, formatPrice);
    expect(card?.primaryImage.src).toBe('https://example.test/medium/link-only.jpg');
  });

  test('falls back to the product name for alt when the selected medium image carries no alt of its own', () => {
    const noAltMedium: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [
        {
          viewType: 'medium',
          images: [
            {
              link: 'https://example.test/medium/no-alt.jpg',
              disBaseLink: 'https://cdn.example.test/medium/no-alt.jpg',
            },
          ],
        },
      ],
    };
    const card = selectRecentlyViewedCard(noAltMedium, formatPrice);
    expect(card?.primaryImage.alt).toBe('Natura Mini Dress');
  });
});

describe('selectRecentlyViewedCard — price without a paired currency (no guessed currency)', () => {
  test('currentPrice is undefined when currency is missing, and formatPrice is never called', () => {
    const spy = vi.fn(formatPrice);
    const card = selectRecentlyViewedCard({ ...FULL, currency: undefined }, spy);
    expect(card?.currentPrice).toBeUndefined();
    expect(spy).not.toHaveBeenCalled();
  });

  test('currentPrice is undefined when price is missing, and formatPrice is never called', () => {
    const spy = vi.fn(formatPrice);
    const card = selectRecentlyViewedCard({ ...FULL, price: undefined }, spy);
    expect(card?.currentPrice).toBeUndefined();
    expect(spy).not.toHaveBeenCalled();
  });

  test('calls the injected formatter exactly once, with the real price and currency, when both are present', () => {
    const spy = vi.fn(formatPrice);
    selectRecentlyViewedCard(FULL, spy);
    expect(spy).toHaveBeenCalledOnce();
    expect(spy).toHaveBeenCalledWith(895, 'AUD');
  });
});

